with order_items_by_product as (select product_id, max(quantity) - min(quantity) as quantity_range, round(stddev(quantity), 2) as stddev_quantity from order_items where unit_price < 120 group by product_id) select p.id, p.product_name, oibp.quantity_range, oibp.stddev_quantity from products p inner join order_items_by_product oibp on p.id = oibp.product_id order by oibp.stddev_quantity desc, id limit 5;
